arguments.argument:
if(other.team != team)
{
    if(!collision_line(x,y-12,other.x,other.y,Obstacle,true,true)) and (!collision_line(x,y-12,other.x,other.y,TeamGate,true,true) and (!collision_line(x,y-12,other.x,other.y,BulletWall,true,true)))
    {
        if weapon == DAMAGE_SOURCE_AXE hitDamage = 80; //Enough to 1-hit a mini and 2-hit any other
        damageSentry(ownerPlayer, other.id, hitDamage);
        other.lastDamageDealer = ownerPlayer;
        other.lastDamageSource = weapon;

        if (!splashHit) {
                instance_destroy(); 
        } else {
                splashAmount -= 1;
                hitDamage -= 13 * pierced;
                pierced += 1;
                if (splashAmount <= 0)
                {
                    splashHit = false;
                }
                alarm[0] = 1 / global.delta_factor;
        }
        playsound(x,y,MeleeHitMapSnd);
    }
    else
        alarm[0] = 1 / global.delta_factor;
} else if weapon == DAMAGE_SOURCE_WRENCH or weapon == DAMAGE_SOURCE_EEFFECT {
    if other.level != 3 {
        if other.built == 0 {
            var amount;
            other.buildrate += 0.25;
            playsound(x,y,MeleeHitMapSnd);
        } else if other.hp < other.maxHp {
            var amount;
            amount = min(other.maxHp-other.hp,10);
            if owner.nutsNBolts >= amount {
                other.hp += amount;
                owner.nutsNBolts -= amount;
            } else {
                other.hp += owner.nutsNBolts;
                owner.nutsNBolts = 0;
            }
            playsound(x,y,MeleeHitMapSnd);
        } else if other.upgrade < other.upgradeMax && other.level < 3 {
            var amount;
            amount = min(other.upgradeMax - other.upgrade, 20);
            if owner.nutsNBolts >= amount {
                owner.nutsNBolts -= amount;
                other.upgrade += amount;
            } else {
                other.upgrade += owner.nutsNBolts;
                owner.nutsNBolts=0;
            }
            playsound(x,y,MeleeHitMapSnd);
        } else playsound(x,y,WrenchFailSnd);
    } else playsound(x,y,WrenchFailSnd);
    instance_destroy();
}
